INSERT INTO `config` VALUES ('calendar', '1^Beta Release^2025-04-20 00:00^Pandanda Rewritten Launches into Official Early Beta!^17^^^^1;2^Easter Egg Hunt Starts^2025-04-06 00:00^Easter Egg Hunt Begins! The Easter Bunny has hidden eggs all over Pandanda Land! Find the eggs and trade them for prizes!^31^Easter Egg Hunt Ends^2025-04-30 00:00^Easter Egg Hunt Ends!^52^6^^^^;18^Sheriff Visit^2025-05-13 11:00^Meet Sheriff and play games alongside him today!^15^^^^1;4^Beta Party Ends^2025-05-23 00:00^Beta Bear Leaves Pandanda taking with him the Beta clothing as Pandanda Rewritten trotts off into the sunset for future updates & changes towards 1.0!^17^^^^1;5^Zing is back^2025-05-24 00:00^Zing is back from his holiday!^24^^^^^^2;62^Bunny Chase Double Coins^2025-06-01 00:00^Get double reward from chasing bunnies in Darby Field!^32^^^^^^;81^Fruits&Veggies Double Coins^2025-06-10 00:00^Earn double coins from collecting and selling fruits and vegetables around Pandanda!^97^^^^^^;82^Summer Festival Begins^2025-06-12 00:00^The summer Festival Arrives at Pandanda!^56^Summer Festival Ends^2025-06-30 00:00^The summer Festival Departs Pandanda!^57^12^^^^;83^Gems Double Coins^2025-06-20 00:00^Earn double coins from collecting and selling gems around Pandanda!^98^^^^^^;84^Clothes Update^2025-05-26 18:00^New Clothing Co. Catalog!^14^^^^^^;85^Furniture Update^2025-05-27 18:00^New Furniture Catalog!^58^^^^^^;86^Bunny Chase Double Coins^2025-05-28 00:00^Get double reward from chasing bunnies in Darby Field!^32^^^^^^;87^Ghosts Double Coins^2025-05-28 00:00^Get double reward from catching ghosts in Misty Hill!^36^^^^^^;88^Zing New Prize^2025-06-01 00:00^Zing has a new prize for you!^0^^^^^^2;89^Zing Departure^2025-06-11 23:59^Zing has gone on holiday!^24^^^^^^;90^All Sellers Double Coins^2025-06-14 00:00^Earn double coins from fishing and selling fish, Collecting and selling trash, vegetables, fruits and gems around Pandanda!^88^^^^^^;91^All Sellers Double Coins^2025-06-15 00:00^Earn double coins from fishing and selling fish, Collecting and selling trash, vegetables, fruits and gems around Pandanda!^88^^^^^^;92^Bunny Chase Double Coins^2025-07-01 00:00^Get double reward from chasing bunnies in Darby Field!^32^^^^^^;93^4th July Celebrations!^2025-07-04 00:00^Celebrate the 4th July across Pandanda!^51^^^^^^7;94^Sheriff Visit^2025-07-09 19:00^Meet Sheriff and play games alongside him today!^15^^^^^^;95^Clothes Update^2025-07-15 19:00^New Clothing Co. Catalog!^14^^^^^^;96^Global Double Coins^2025-07-18 00:00^Earn double coins from fishing and selling fish, Collecting and selling trash, vegetables, fruits and gems around Pandanda!^88^^^^^^;97^Gems Double Coins^2025-07-21 00:00^Earn double coins from collecting and selling gems around Pandanda!^98^^^^^^;98^Zing is back^2025-07-22 00:00^Zing is back from his holiday!^24^^^^^^2;99^Beach Party^2025-07-26 15:00^Get ready for a sun-soaked beach party! Join the relaxing fishing night over at Tiki Isle!^72^^^^^^7;100^Red Color Day^2025-07-31 19:00^Dress up and show up to the Red Color Day!^73^^^^^^;101^Fishing Double Coins^2025-07-13 00:00^Earn double coins from fishing and selling all fish on Pandanda!^94^^^^^^;102^Fishing Double Coins^2025-07-26 15:00^Earn double coins from fishing and selling all fish on Pandanda!^94^^^^^^;103^Zing New Prize^2025-08-02 00:00^Zing has a new prize for you!^23^^^^^^2;104^Zing Departure^2025-08-07 00:00^Zing has gone on holiday!^24^^^^^^;105^Harvest Festival Begins^2025-08-08 00:00^Harvest Festival arrives in Pandanda!^59^Harvest Festival Ends^2025-08-31 00:00^Harvest Festival is now over!^60^13^;106^Bunny Chase Double Coins^2025-08-11 00:00^Get double reward from chasing bunnies in Darby Field!^32^^^^^^;107^Ghosts Double Coins^2025-08-16 00:00^Get double reward from catching ghosts in Misty Hill!^36^^^^^^;108^Sheriff Visit^2025-08-20 18:30^Meet Sheriff and play games alongside him today!^15^^^^^^;109^Orange Color Day^2025-08-25 18:00^Dress up and show up to the Orange Color Day!^73