-- ----------------------------
-- Table structure for users
-- ----------------------------
DROP TABLE IF EXISTS `users`;
CREATE TABLE `users`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `username` varchar(255) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `email` varchar(255) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `password` varchar(255) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `active` int NOT NULL DEFAULT 1,
  `regdate` timestamp(0) NOT NULL DEFAULT current_timestamp(0),
  `crumbs` longtext CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL,
  `ip` text CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL,
  `ubdate` varchar(255) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `color` varchar(4) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT 'P001',
  `reset_token` varchar(64) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `reset_token_expiry` datetime(0) NULL DEFAULT NULL,
  `safeChat` tinyint NULL DEFAULT 0,
  `umdate` varchar(255) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `username`(`username`) USING BTREE,
  UNIQUE INDEX `email`(`email`) USING BTREE,
  INDEX `username_2`(`username`) USING BTREE,
  INDEX `username_3`(`username`) USING BTREE,
  INDEX `idx_users_umdate`(`umdate`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 220 CHARACTER SET = latin1 COLLATE = latin1_swedish_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Event structure for delete_old_messages
-- ----------------------------
DROP EVENT IF EXISTS `delete_old_messages`;
delimiter ;;
CREATE EVENT `delete_old_messages`
ON SCHEDULE
EVERY '1' DAY STARTS '2025-05-26 19:55:21'
DO DELETE FROM messages
  WHERE time < NOW() - INTERVAL 30 DAY
;;
delimiter ;

SET FOREIGN_KEY_CHECKS = 1;
